* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: #f4f6f9;
  color: #333;
}

h1 {
  text-align: center;
  padding: 18px 0 6px;
  font-size: 1.5rem;
  color: #222;
}

.container {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: center;
  gap: 24px;
  padding: 10px 24px 24px;
  max-width: 1600px;
  margin: 0 auto;
}

/* ---------- Bubble chart ---------- */
.chart-panel {
  flex: 1 1 55%;
  min-width: 0;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 1px 4px rgba(0,0,0,.1);
  padding: 12px;
}

.chart-panel h2 {
  font-size: 1rem;
  margin-bottom: 6px;
  text-align: center;
  color: #444;
}

#bubble-chart {
  width: 100%;
}

#bubble-chart svg {
  display: block;
  margin: 0 auto;
}

.bubble-label {
  pointer-events: none;
  font-size: 10px;
  font-weight: 600;
  fill: #fff;
  text-anchor: middle;
  dominant-baseline: central;
}

.bubble {
  cursor: pointer;
  stroke: #fff;
  stroke-width: 1.2;
  transition: stroke 0.15s, stroke-width 0.15s;
}

.bubble.selected {
  stroke: #222;
  stroke-width: 3;
}

/* Tooltip */
.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(30, 30, 30, .92);
  color: #fff;
  padding: 8px 12px;
  border-radius: 5px;
  font-size: 13px;
  line-height: 1.45;
  max-width: 280px;
  z-index: 10;
  opacity: 0;
  transition: opacity .15s;
}

.tooltip .tt-ticker {
  font-weight: 700;
  font-size: 14px;
}

.tooltip .tt-name {
  margin-top: 2px;
}

.tooltip .tt-sector {
  margin-top: 2px;
  color: #aed6f1;
}

/* Legend */
.legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px 18px;
  margin-top: 8px;
  font-size: 12px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  cursor: default;
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  flex-shrink: 0;
}

/* ---------- Data table ---------- */
.table-panel {
  flex: 1 1 40%;
  min-width: 0;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 1px 4px rgba(0,0,0,.1);
  padding: 12px;
  max-height: 700px;
  display: flex;
  flex-direction: column;
}

.table-panel h2 {
  font-size: 1rem;
  margin-bottom: 6px;
  text-align: center;
  color: #444;
}

.table-wrap {
  overflow-y: auto;
  flex: 1;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

#stock-table thead {
  position: sticky;
  top: 0;
  z-index: 2;
}

#stock-table th {
  background: #3a3f51;
  color: #fff;
  padding: 8px 10px;
  text-align: left;
  font-weight: 600;
  white-space: nowrap;
}

#stock-table td {
  padding: 7px 10px;
  border-bottom: 1px solid #e8e8e8;
  white-space: nowrap;
}

#stock-table tbody tr {
  cursor: pointer;
  transition: background .12s;
}

#stock-table tbody tr:hover {
  background: #eef4fb;
}

#stock-table tbody tr.selected {
  background: #d4e6f9;
  font-weight: 600;
}

