(function () {
  "use strict";

  /* ------------------------------------------------------------------ */
  /*  Globals                                                           */
  /* ------------------------------------------------------------------ */
  const BUBBLE_W = 720,
        BUBBLE_H = 620;

  const sectorColor = d3.scaleOrdinal()
    .domain(["Information Technology", "Industry", "Energy", "Financial", "ETF"])
    .range(["#4e79a7", "#e15759", "#76b7b2", "#f28e2b", "#b07aa1"]);

  /* Cluster center positions (relative to chart center) */
  const sectorCenters = {
    "Information Technology": { x: -140, y: -120 },
    "Industry":              { x:  160, y: -120 },
    "Energy":                { x: -140, y:  130 },
    "Financial":             { x:  160, y:  130 },
    "ETF":                   { x:    0, y:    0 }
  };

  /* ------------------------------------------------------------------ */
  /*  Helpers                                                           */
  /* ------------------------------------------------------------------ */

  /** Format market cap to human-readable string (e.g. "1.64T") */
  function fmtCap(v) {
    if (v == null || isNaN(v) || v === "") return "N/A";
    v = +v;
    if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (v >= 1e9)  return (v / 1e9).toFixed(2)  + "B";
    if (v >= 1e6)  return (v / 1e6).toFixed(2)  + "M";
    return v.toLocaleString();
  }

  /* ------------------------------------------------------------------ */
  /*  Load data                                                         */
  /* ------------------------------------------------------------------ */
  d3.csv("data/stock-descriptions.csv").then(function (raw) {
    const data = raw.map(function (d) {
      return {
        ticker:    d.ticker,
        name:      d["full name"],
        sector:    d.sector,
        marketCap: d.marketCap === "" ? null : +d.marketCap,
        country:   d.country   || null,
        website:   d.website   || null,
        isETF:     d.sector === "ETF"
      };
    });

    drawBubbleChart(data);
    drawTable(data);
  });

  /* ------------------------------------------------------------------ */
  /*  Bubble chart                                                      */
  /* ------------------------------------------------------------------ */
  let selectedTicker = null;       // shared state

  function drawBubbleChart(data) {
    const cx = BUBBLE_W / 2,
          cy = BUBBLE_H / 2;

    /* ---- radius scale ---- */
    const caps = data.filter(d => d.marketCap != null).map(d => d.marketCap);
    const rScale = d3.scaleSqrt()
      .domain([d3.min(caps), d3.max(caps)])
      .range([14, 56]);

    const ETF_R = 16;   // uniform radius for ETFs

    data.forEach(d => {
      d.r = d.isETF ? ETF_R : rScale(d.marketCap);
    });

    /* ---- SVG ---- */
    const svg = d3.select("#bubble-chart")
      .append("svg")
      .attr("viewBox", [0, 0, BUBBLE_W, BUBBLE_H])
      .attr("width", BUBBLE_W)
      .attr("height", BUBBLE_H);

    /* ---- Tooltip ---- */
    const tooltip = d3.select("body").append("div").attr("class", "tooltip");

    /* ---- Force simulation ---- */
    const simulation = d3.forceSimulation(data)
      .force("x", d3.forceX(d => cx + sectorCenters[d.sector].x).strength(0.15))
      .force("y", d3.forceY(d => cy + sectorCenters[d.sector].y).strength(0.15))
      .force("collide", d3.forceCollide(d => d.r + 2).strength(1))
      .force("charge", d3.forceManyBody().strength(-5))
      .alphaDecay(0.02)
      .on("tick", ticked);

    /* ---- Node groups ---- */
    const node = svg.selectAll(".node")
      .data(data)
      .join("g")
      .attr("class", "node");

    node.append("circle")
      .attr("class", "bubble")
      .attr("r", d => d.r)
      .attr("fill", d => sectorColor(d.sector));

    node.append("text")
      .attr("class", "bubble-label")
      .text(d => d.ticker)
      .style("font-size", d => Math.max(8, d.r * 0.38) + "px");

    /* ---- Interactions ---- */
    node.on("mouseover", function (event, d) {
        if (d.isETF) return;
        tooltip
          .style("opacity", 1)
          .html(
            '<div class="tt-ticker">' + d.ticker + '</div>' +
            '<div class="tt-name">' + d.name + '</div>' +
            '<div class="tt-sector">' + d.sector + '</div>'
          );
      })
      .on("mousemove", function (event) {
        tooltip
          .style("left", (event.pageX + 14) + "px")
          .style("top",  (event.pageY - 28) + "px");
      })
      .on("mouseout", function () {
        tooltip.style("opacity", 0);
      })
      .on("click", function (event, d) {
        selectStock(d.ticker);
      });

    function ticked() {
      node.attr("transform", d => "translate(" + d.x + "," + d.y + ")");
    }

    /* ---- Legend ---- */
    const legendDiv = d3.select("#bubble-chart").append("div").attr("class", "legend");
    sectorColor.domain().forEach(function (s) {
      const item = legendDiv.append("div").attr("class", "legend-item");
      item.append("div")
        .attr("class", "legend-swatch")
        .style("background", sectorColor(s));
      item.append("span").text(s);
    });

    /* Expose highlight updater */
    window._updateBubbleHighlight = function (ticker) {
      svg.selectAll(".bubble")
        .classed("selected", d => d.ticker === ticker);
    };
  }

  /* ------------------------------------------------------------------ */
  /*  Data table                                                        */
  /* ------------------------------------------------------------------ */
  function drawTable(data) {
    const columns = [
      { key: "ticker",    label: "Ticker" },
      { key: "name",      label: "Company Name" },
      { key: "sector",    label: "Sector" },
      { key: "marketCap", label: "Market Cap" }
    ];

    const table = d3.select("#stock-table");

    /* thead */
    table.append("thead").append("tr")
      .selectAll("th")
      .data(columns)
      .join("th")
      .text(d => d.label);

    /* tbody */
    const rows = table.append("tbody")
      .selectAll("tr")
      .data(data)
      .join("tr")
      .attr("data-ticker", d => d.ticker);

    rows.selectAll("td")
      .data(d => columns.map(c => {
        if (c.key === "marketCap") return fmtCap(d.marketCap);
        return d[c.key];
      }))
      .join("td")
      .text(d => d);

    /* Click row -> select */
    rows.on("click", function (event, d) {
      selectStock(d.ticker);
    });

    /* Expose highlight updater */
    window._updateTableHighlight = function (ticker) {
      d3.select("#stock-table tbody")
        .selectAll("tr")
        .classed("selected", d => d.ticker === ticker);

      /* Scroll selected row into view */
      const row = d3.select('#stock-table tbody tr[data-ticker="' + ticker + '"]').node();
      if (row) {
        row.scrollIntoView({ block: "nearest", behavior: "smooth" });
      }
    };
  }

  /* ------------------------------------------------------------------ */
  /*  Shared selection logic                                            */
  /* ------------------------------------------------------------------ */
  function selectStock(ticker) {
    /* Toggle off if already selected */
    if (selectedTicker === ticker) {
      selectedTicker = null;
      window._updateBubbleHighlight(null);
      window._updateTableHighlight(null);
      return;
    }
    selectedTicker = ticker;
    window._updateBubbleHighlight(ticker);
    window._updateTableHighlight(ticker);
  }
})();

